#!/usr/bin/env python3
"""Resume checks after correcting the std-gated ignored-test count expectation."""
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import time

ROOT=Path('/Users/lanxingcan/Workspace/zstdoxize')
PREFIX='/tmp/zstdoxide-module11-stream'
OUT=Path(PREFIX+'-evidence.json')
FEATURES='unsafe-byte-cursor,unsafe-bitstream,unsafe-history,unsafe-ring-history,unsafe-fse,unsafe-fse-encoder,unsafe-huffman,unsafe-huffman-codebook,unsafe-match-table,unsafe-match-chain,unsafe-dictionary,unsafe-training'
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def summaries(text):
    return [dict(zip(('passed','failed','ignored','measured','filtered_out'),map(int,row)))
            for row in re.findall(r'test result: ok\. (\d+) passed; (\d+) failed; (\d+) ignored; (\d+) measured; (\d+) filtered out;',text)]

def main():
    original=Path(PREFIX+'-guard-diagnostic.json')
    if original.exists(): raise RuntimeError('Refusing to overwrite first-run diagnostic')
    original.write_bytes(OUT.read_bytes())
    e=json.loads(OUT.read_text())
    last=e['commands'][-1]
    if last['name']!='no-std-safe' or last['exit_code']!=0 or sum(s['passed'] for s in last['summaries'])!=31 or sum(s['ignored'] for s in last['summaries'])!=0:
        raise RuntimeError('Unexpected continuation point')
    last['expected_count_guard']=True
    last['count_guard_correction']='The optional official C test is gated on std and absent under no-default-features: expected 31 passed and 0 ignored. Initial runner wrongly expected 1 ignored; Cargo itself succeeded.'
    e['first_runner_diagnostic']={'path':str(original),'sha256':sha(original)}
    e['continuation_runner']={'path':__file__,'sha256':sha(__file__)}
    env=os.environ.copy();env.update(e['environment'])
    commands=[('no-std-all',['cargo','+nightly-2026-10-08','test','--offline','--locked','--lib','--no-default-features','--features',FEATURES,'stream_encode::tests::'],True)]
    for name,features in [('safe',[]),('all',['--features',FEATURES])]:
        commands.append(('check-no-std-'+name,['cargo','+nightly-2026-10-08','check','--offline','--locked','--lib','--no-default-features',*features],False))
    for name,features in [('safe',[]),('all',['--all-features'])]:
        commands.append(('clippy-lib-'+name,['cargo','+nightly-2026-10-08','clippy','--offline','--locked','--lib',*features,'--','-D','warnings'],False))
    commands.extend([
        ('format',['rustfmt','+nightly-2026-10-08','--edition','2024','--check','src/stream_encode.rs'],False),
        ('diff-check',['git','diff','--check','--','src/stream_encode.rs'],False),
    ])
    def save(): OUT.write_text(json.dumps(e,indent=2)+'\n')
    save()
    for name,command,is_test in commands:
        if sha(ROOT/e['owned_source'])!=e['source_sha256_before']: raise RuntimeError('Owned source changed')
        log=Path(PREFIX+'-'+name+'.log');start=time.monotonic();print('START '+name,flush=True)
        with log.open('wb') as h:r=subprocess.run(command,cwd=ROOT,env=env,stdout=h,stderr=subprocess.STDOUT)
        elapsed=time.monotonic()-start;s=summaries(log.read_text());passed=sum(x['passed'] for x in s);ignored=sum(x['ignored'] for x in s)
        valid=r.returncode==0 and(not is_test or(passed==31 and ignored==0))
        e['commands'].append({'name':name,'command':command,'cwd':str(ROOT),'exit_code':r.returncode,'seconds':round(elapsed,4),'summaries':s,'expected_count_guard':valid,'log':str(log),'log_sha256':sha(log),'source_sha256_after':sha(ROOT/e['owned_source'])})
        save();print(f'END {name} exit={r.returncode} passed={passed} ignored={ignored} guard={valid}',flush=True)
        if not valid: raise RuntimeError('Check failed: '+name)
    core=Path(PREFIX+'-core-manifest.json');manifest=json.loads(core.read_text())
    changed=[p for p,v in manifest['files'].items() if sha(ROOT/p)!=v['sha256']]
    e['core_manifest']={'path':str(core),'sha256':sha(core),'file_count':len(manifest['files']),'changed_after_capture':changed,'qualification':manifest['scope']}
    e['head_after']=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
    e['source_sha256_after']=sha(ROOT/e['owned_source']);e['source_unchanged']=e['source_sha256_after']==e['source_sha256_before']
    e['passed']=sum(s['passed'] for c in e['commands'] for s in c['summaries']);e['ignored']=sum(s['ignored'] for c in e['commands'] for s in c['summaries'])
    e['completed']=e['source_unchanged'];save();print('EVIDENCE '+str(OUT)+' sha256='+sha(OUT),flush=True)
if __name__=='__main__':main()

